//! MCP resources and prompts a project offers besides its tools: text
//! documents written in mcp-forge, and prompt templates with arguments.
//! (Database schemas and imported specs are generated by forge-mcp.)

use std::collections::HashSet;

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};
use uuid::Uuid;

use crate::db::is_valid_sql_param_name;
use crate::nosql::{placeholders_in, render_str};
use crate::validate::{is_valid_name, ValidationErrors, MAX_NAME_LEN};

pub const MAX_RESOURCE_BYTES: usize = 1_000_000;
pub const MAX_PROMPT_BYTES: usize = 100_000;
pub const RESOURCE_MIME_TYPES: [&str; 5] = [
    "text/markdown",
    "text/plain",
    "application/json",
    "text/csv",
    "application/yaml",
];

/// URI scheme of resources written in mcp-forge.
pub const RESOURCE_URI_PREFIX: &str = "forge://resources/";

fn default_mime() -> String {
    "text/markdown".into()
}

/// Create/replace payload for a text resource.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ResourceInput {
    pub name: String,
    #[serde(default)]
    pub description: String,
    #[serde(default = "default_mime")]
    pub mime_type: String,
    pub content: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ResourceDef {
    pub id: Uuid,
    pub project_id: Uuid,
    pub name: String,
    pub description: String,
    pub mime_type: String,
    pub content: String,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
}

impl ResourceDef {
    pub fn uri(&self) -> String {
        format!("{RESOURCE_URI_PREFIX}{}", self.name)
    }
}

impl ResourceInput {
    pub fn validate(&self) -> Result<(), ValidationErrors> {
        let mut errs = ValidationErrors::default();
        if !is_valid_name(&self.name) {
            errs.push(
                "name",
                format!("must be 1–{MAX_NAME_LEN} characters of a-z, A-Z, 0-9, _ or -"),
            );
        }
        if !RESOURCE_MIME_TYPES.contains(&self.mime_type.as_str()) {
            errs.push(
                "mime_type",
                format!("use one of: {}", RESOURCE_MIME_TYPES.join(", ")),
            );
        }
        if self.content.len() > MAX_RESOURCE_BYTES {
            errs.push(
                "content",
                format!("must be at most {MAX_RESOURCE_BYTES} bytes"),
            );
        } else if self.mime_type == "application/json"
            && serde_json::from_str::<Value>(&self.content).is_err()
        {
            errs.push("content", "isn't valid JSON");
        }
        if self.description.len() > 2_000 {
            errs.push("description", "must be at most 2000 characters");
        }
        errs.into_result()
    }
}

/// An argument of a prompt template, filled in where `{{name}}` appears.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PromptArg {
    pub name: String,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub required: bool,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PromptInput {
    pub name: String,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub arguments: Vec<PromptArg>,
    pub template: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PromptDef {
    pub id: Uuid,
    pub project_id: Uuid,
    pub name: String,
    pub description: String,
    pub arguments: Vec<PromptArg>,
    pub template: String,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
}

impl PromptInput {
    pub fn validate(&self) -> Result<(), ValidationErrors> {
        let mut errs = ValidationErrors::default();
        if !is_valid_name(&self.name) {
            errs.push(
                "name",
                format!("must be 1–{MAX_NAME_LEN} characters of a-z, A-Z, 0-9, _ or -"),
            );
        }
        if self.template.trim().is_empty() {
            errs.push("template", "must not be empty");
        } else if self.template.len() > MAX_PROMPT_BYTES {
            errs.push(
                "template",
                format!("must be at most {MAX_PROMPT_BYTES} bytes"),
            );
        }
        let mut used = Vec::new();
        placeholders_in(&self.template, &mut used);
        let mut seen = HashSet::new();
        for (i, a) in self.arguments.iter().enumerate() {
            if !is_valid_sql_param_name(&a.name) {
                errs.push(
                    format!("arguments[{i}].name"),
                    "must start with a letter or _ and contain only a-z, A-Z, 0-9 or _",
                );
            } else if !seen.insert(a.name.to_lowercase()) {
                errs.push(
                    format!("arguments[{i}].name"),
                    format!("duplicate argument `{}`", a.name),
                );
            } else if !used.contains(&a.name) {
                errs.push(
                    format!("arguments[{i}].name"),
                    format!(
                        "`{}` isn't used; write {{{{{}}}}} in the template",
                        a.name, a.name
                    ),
                );
            }
        }
        for name in used {
            if !self.arguments.iter().any(|a| a.name == name) {
                errs.push(
                    "arguments",
                    format!("{{{{{name}}}}} has no matching argument"),
                );
            }
        }
        errs.into_result()
    }
}

impl PromptDef {
    pub fn input(&self) -> PromptInput {
        PromptInput {
            name: self.name.clone(),
            description: self.description.clone(),
            arguments: self.arguments.clone(),
            template: self.template.clone(),
        }
    }

    /// The template with arguments filled in; fails when a required one is
    /// missing.
    pub fn render(&self, args: &Map<String, Value>) -> Result<String, String> {
        for a in &self.arguments {
            let given = args
                .get(&a.name)
                .is_some_and(|v| !v.is_null() && v.as_str() != Some(""));
            if a.required && !given {
                return Err(format!("`{}` is required", a.name));
            }
        }
        Ok(render_str(&self.template, args))
    }
}

impl ResourceDef {
    pub fn input(&self) -> ResourceInput {
        ResourceInput {
            name: self.name.clone(),
            description: self.description.clone(),
            mime_type: self.mime_type.clone(),
            content: self.content.clone(),
        }
    }
}

